import request from '../utils/request';
export function add(data) {
    return request({
        url: 'im/friend/add',
        method: 'post',
        data
    });
}
export function del(data) {
    return request({
        url: 'im/friend/delete',
        method: 'post',
        data
    });
}
export function setBlack(data) {
    return request({
        url: 'im/friend/setBlack',
        method: 'post',
        data
    });
}
export function getBlackList() {
    return request({
        url: 'im/friend/getBlackList'
    });
}
export function getApplicationList() {
    return request({
        url: 'im/friend/getApplicationList'
    });
}
export function getApplicationUnreadCount() {
    return request({
        url: 'im/friend/getApplicationUnreadCount'
    });
}
export function refuseApplication(data) {
    return request({
        url: 'im/friend/refuseApplication',
        method: 'post',
        data
    });
}
export function acceptApplication(data) {
    return request({
        url: 'im/friend/acceptApplication',
        method: 'post',
        data
    });
}
export function getList(params) {
    return request({
        url: 'im/friend/getList',
        params
    });
}
